<script setup>
import { onMounted, reactive, ref, watch } from 'vue'; import { useRouter } from 'vue-router'; import { api } from '../api'; import { useAuthStore } from '../stores/auth'; import RecipeTile from '../components/RecipeTile.vue'; import FlavorBloom from '../components/FlavorBloom.vue'; import { emitMotion } from '../motion'; import { Download, KeyRound, Save, Trash2, UserRound } from 'lucide-vue-next'
const auth=useAuthStore(),router=useRouter(),tab=ref('favorites'),me=ref(null),favorites=ref([]),loading=ref(true),error=ref(''),notice=ref('');const form=reactive({display_name:'',sweetness:5,sourness:5,strong:5});const passwords=reactive({current_password:'',new_password:''})
watch(()=>[form.sweetness,form.sourness,form.strong],values=>emitMotion('profile',{label:values.join('-')}))
async function load(){try{const [user,favs]=await Promise.all([api.me.get(),api.me.favorites()]);me.value=user;favorites.value=favs.items;form.display_name=user.display_name||'';form.sweetness=user.profile?.sweetness??5;form.sourness=user.profile?.sourness??5;form.strong=user.profile?.strong??5}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(){try{me.value=await api.me.update({display_name:form.display_name,profile:{sweetness:form.sweetness,sourness:form.sourness,strong:form.strong}});auth.user={...auth.user,display_name:form.display_name};notice.value='个人资料已保存'}catch(e){error.value=e.message}}
async function removeFavorite(recipe){await api.me.removeFavorite(recipe.name);favorites.value=favorites.value.filter(x=>x.name!==recipe.name)}
async function exportData(){const data=await api.me.export();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bartenderai-data.json';a.click();URL.revokeObjectURL(url)}
async function changePassword(){try{await api.me.changePassword(passwords);notice.value='密码已修改，请重新登录';await auth.logout();router.push('/login')}catch(e){error.value=e.message}}
async function deleteAccount(){if(window.prompt('此操作不可恢复。请输入 DELETE 确认注销账号')!=='DELETE')return;await api.me.remove();await auth.logout();router.push('/login')}
onMounted(load)
</script>
<template><div class="page"><header class="page-head"><div><h1>收藏与个人中心</h1><p>管理口味画像、喝后反馈、账号安全和你的数据。</p></div></header><div class="segmented tabs"><button :class="{active:tab==='favorites'}" @click="tab='favorites'">收藏 {{favorites.length}}</button><button :class="{active:tab==='profile'}" @click="tab='profile'">口味画像</button><button :class="{active:tab==='security'}" @click="tab='security'">账号安全</button></div><div v-if="error" class="error-box">{{error}}</div><div v-if="notice" class="notice">{{notice}}</div>
<div v-if="loading" class="state">正在读取个人资料...</div><section v-else-if="tab==='favorites'"><div v-if="!favorites.length" class="state"><div><strong>还没有收藏配方</strong><router-link class="btn" to="/explore">去配方探索</router-link></div></div><div v-else class="grid grid-4"><RecipeTile v-for="item in favorites" :key="item.name" :recipe="item.recipe" favorite @favorite="removeFavorite"/></div></section>
<section v-else-if="tab==='profile'" class="profile-grid">
  <div class="panel panel-pad form"><h2 class="section-title"><UserRound :size="18"/>基础资料</h2><div class="field"><label>邮箱</label><input class="input" :value="me.email" disabled/></div><div class="field"><label>显示名称</label><input class="input" v-model="form.display_name" maxlength="80"/></div><h2 class="section-title flavor-title">口味偏好</h2><label class="range">甜度偏好 <b>{{form.sweetness}}</b><input type="range" min="1" max="10" v-model.number="form.sweetness"/></label><label class="range">酸度偏好 <b>{{form.sourness}}</b><input type="range" min="1" max="10" v-model.number="form.sourness"/></label><label class="range">酒精感偏好 <b>{{form.strong}}</b><input type="range" min="1" max="10" v-model.number="form.strong"/></label><button class="btn primary" @click="save"><Save :size="16"/>保存资料</button></div>
  <aside class="panel panel-pad progress"><FlavorBloom :sweetness="form.sweetness" :sourness="form.sourness" :strong="form.strong"/><div class="profile-level"><h2>{{me.progress.level.name}}</h2><strong>{{me.progress.xp}} XP</strong><p>距离下一等级还需 {{me.progress.level.xp_to_next}} XP</p><div><span :style="{width:`${Math.min(100,me.progress.level.xp_to_next?me.progress.xp/(me.progress.xp+me.progress.level.xp_to_next)*100:100)}%`}"></span></div><small>喝后评分中的明确偏好会自动更新画像。</small></div></aside>
</section>
<section v-else class="security-grid"><div class="panel panel-pad form"><h2 class="section-title"><KeyRound :size="18"/>修改密码</h2><div class="field"><label>当前密码</label><input class="input" type="password" v-model="passwords.current_password"/></div><div class="field"><label>新密码</label><input class="input" type="password" v-model="passwords.new_password" minlength="10"/></div><button class="btn primary" @click="changePassword">更新密码</button></div><aside class="panel panel-pad data-actions"><h2 class="section-title">数据管理</h2><p>导出账号、画像、酒柜、收藏、会话和反馈记录。</p><button class="btn" @click="exportData"><Download :size="16"/>导出 JSON</button><hr/><h3>注销账号</h3><p>会永久删除账号及关联业务数据，操作不可撤销。</p><button class="btn danger" @click="deleteAccount"><Trash2 :size="16"/>永久注销</button></aside></section></div></template>
<style scoped>.tabs{margin-bottom:20px}.notice{background:#e6f2ea;color:var(--green);padding:10px;border-radius:6px;margin-bottom:12px}.profile-grid,.security-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px}.form{display:grid;gap:16px;align-content:start}.section-title{display:flex;align-items:center;gap:7px}.flavor-title{margin-top:9px}.range{display:grid;grid-template-columns:1fr 28px;gap:5px;font-size:13px}.range input{grid-column:1/3;accent-color:var(--green)}.progress{display:grid;align-content:start;padding-top:10px;overflow:hidden}.profile-level{border-top:1px solid var(--line);padding:16px 10px 4px}.profile-level h2{margin:0}.profile-level>strong{font-size:30px;color:var(--green)}.progress p,.progress small,.data-actions p{color:var(--muted);font-size:12px}.profile-level>div{height:8px;background:#e2e6e2;border-radius:5px;margin:14px 0;overflow:hidden}.profile-level>div span{display:block;height:100%;background:var(--amber);border-radius:5px;transition:width .5s}.data-actions{align-content:start}.data-actions .btn{width:100%}.data-actions hr{border:0;border-top:1px solid var(--line);margin:20px 0}.data-actions h3{font-size:14px}@media(max-width:760px){.profile-grid,.security-grid{grid-template-columns:1fr}.tabs{display:flex;overflow:auto}.tabs button{white-space:nowrap}.progress{order:-1}}</style>
